package cn.lili.modules.community.p0.stage45;
import org.junit.jupiter.api.Test;import com.google.gson.*;import java.util.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;import static org.junit.jupiter.api.Assertions.*;
class Stage45ConsistencyTest{
 JsonObject normal(){return object(map("orderId","123","paidCent",1100,"goodsCent",1000,"freightCent",100,"originalCommissionCent",50,"goodsRefundCent",200,"feeRefundCent",0,"lateRefundCent",0,"sharedCent",50,"returnedCent",10,"projectedGrossCent",900,"projectedCommissionCent",40,"projectedNetCent",860));}
 Set<String> codes(JsonObject c){var out=new HashSet<String>();for(var f:Stage45Consistency.inspect(c))out.add(String.valueOf(f.get("code")));return out;}
 @Test void knownExactAmountsNeedNoFinding(){assertTrue(Stage45Consistency.inspect(normal()).isEmpty());}
 @Test void eightRequiredClassesHaveIndependentObservableFindings(){var cases=new LinkedHashMap<String,JsonObject>();for(var p:Map.of("parentMismatch","PARENT_CHILD_CONSERVATION","missingPayment","MISSING_PAYMENT","duplicatePayment","DUPLICATE_PAYMENT","orphan","ORPHAN_RECORD","identityMismatch","STORE_SUBTRANSACTION_MISMATCH").entrySet()){var c=normal();c.addProperty(p.getKey(),true);cases.put(p.getValue(),c);}var over=normal();over.addProperty("goodsRefundCent",1001);cases.put("REFUND_LIMIT",over);over=normal();over.addProperty("returnedCent",51);cases.put("SHARE_OR_RETURN_LIMIT",over);over=normal();over.addProperty("projectedNetCent",861);cases.put("SUMMARY_NOT_CONVERGED",over);assertEquals(8,cases.size());cases.forEach((code,c)->assertTrue(codes(c).contains(code),code));}
 @Test void missingProjectionTimeAndInFlightEvidenceStayPending(){var c=normal();c.addProperty("projectionPending",true);var r=Stage45Consistency.inspect(c);assertEquals(1,r.size());assertEquals("PENDING",r.getFirst().get("severity"));c=normal();c.addProperty("missingPayment",true);c.addProperty("paymentPending",true);assertEquals("PENDING",Stage45Consistency.inspect(c).getFirst().get("severity"));}
 @Test void feeAndLateRefundShareTheOriginalPaidCeiling(){var c=normal();c.addProperty("goodsRefundCent",1000);c.addProperty("feeRefundCent",100);c.addProperty("lateRefundCent",1);assertTrue(codes(c).contains("REFUND_LIMIT"));c=normal();c.addProperty("sharedCent",51);assertTrue(codes(c).contains("SHARE_OR_RETURN_LIMIT"));}
}
